{"code": "src = inspect.getsource(rlm.mcp_base)
# Find timeout-related settings
for i, line in enumerate(src.split('\n')):
    if 'timeout' in line.lower() or 'read_timeout' in line.lower() or 'Timeout' in line:
        print(f"Line {i}: {line}")
"}

{"code": "
# Discover available tools
tools = await nethack.list_tools()
for tool in tools:
    print(f"=== {tool['name']} ===")
    print(tool.get('description', 'N/A'))
    schema = tool.get('inputSchema', {})
    if schema.get('properties'):
        for prop, info in schema['properties'].items():
            print(f"  {prop}: {info.get('type', '?')} - {info.get('description', '')}")
    print()
"}

{"code": "
# Let's look at the argument schemas for key tools
import inspect
for t in ['np_move_to', 'np_down', 'np_explore_level', 'np_melee_attack', 'np_pickup', 'rollback', 'np_rest', 'np_look']:
    print(f"=== {t} ===")
    try:
        help(getattr(nethack, t))
    except:
        pass
    print()
"}

{"code": "
# Let's get the full tool schemas from the server
for tool in tools:
    name = tool['name']
    schema = tool.get('inputSchema', {})
    if schema.get('properties'):
        print(f"=== {name} ===")
        print(f"  Properties: {list(schema['properties'].keys())}")
        for prop, info in schema['properties'].items():
            print(f"    {prop}: type={info.get('type', '?')}, desc={info.get('description', 'N/A')}")
        if schema.get('required'):
            print(f"  Required: {schema['required']}")
        print()
    elif name not in ['np_explore_level', 'np_look', 'np_rest']:
        print(f"=== {name} === (no args)")
        print()
"}

