{"code": "
# The server seems to be consistently timing out. Let me check if there's a settings file with the URL
import os, json, glob

# Look for settings.json
for root, dirs, files in os.walk('/tmp'):
    for f in files:
        if f == 'settings.json':
            path = os.path.join(root, f)
            print(f"Found: {path}")
            try:
                with open(path) as fh:
                    data = json.load(fh)
                if 'mcpServers' in data or 'nethack' in str(data):
                    print(json.dumps(data, indent=2))
            except:
                print(f"  (could not parse)")
"}

