import asyncio

async def call_with_retry(tool_name, max_retries=3, **kwargs):
    """Call a nethack tool with retry on timeout."""
    for attempt in range(max_retries):
        try:
            method = getattr(nethack, tool_name)
            result = await method(**kwargs) if kwargs else await method()
            return result
        except Exception as e:
            if attempt < max_retries - 1:
