await asyncio.wait_for(nethack.np_move_to(x=33, y=3), timeout=300)

# Search at multiple positions in the top room
search_positions = [(33,3), (36,3), (34,5), (37,5)]
for pos in search_positions:
    await asyncio.wait_for(nethack.np_move_to(x=pos[0], y=pos[1]), timeout=300)
    for i in range(15):
        result = await asyncio.wait_for(nethack.np_press_key(key='s'), timeout=120)
        if "find" in result.lower() and "hidden" in result.lower():
            print(f"Found secret door at {pos} on search {i}!")
            print(result)
            break
        if i == 14:
            print(f"No secret door at {pos}")
"}

